    '*[_type == "project" && slug.current == $slug][0]{\n  ...{\n  _id,\n  title,\n  "slug": slug.current,\n  summary,\n  location,\n  completed,\n  "before": before{\n  ...,\n  "alt": coalesce(alt, ""),\n  asset->{_id, url, "width": metadata.dimensions.width, "height": metadata.dimensions.height, "lqip": metadata.lqip}\n},\n  "after": after{\n  ...,\n  "alt": coalesce(alt, ""),\n  asset->{_id, url, "width": metadata.dimensions.width, "height": metadata.dimensions.height, "lqip": metadata.lqip}\n}\n},\n  _updatedAt,\n  "gallery": gallery[]{\n  ...,\n  "alt": coalesce(alt, ""),\n  asset->{_id, url, "width": metadata.dimensions.width, "height": metadata.dimensions.height, "lqip": metadata.lqip}\n},\n  body,\n  "service": service->{\n  _id,\n  title,\n  "slug": slug.current,\n  icon,\n  menuSummary,\n  cardSummary,\n  isEmergency,\n  whatsappNoun,\n  "cardImage": cardImage{\n  ...,\n  "alt": coalesce(alt, ""),\n  asset->{_id, url, "width": metadata.dimensions.width, "height": metadata.dimensions.height, "lqip": metadata.lqip}\n}\n},\n  "area": area->{title, "slug": slug.current},\n  seo{metaTitle, metaDescription, noindex, canonicalOverride, extraJsonLd, "ogImage": ogImage{\n  ...,\n  "alt": coalesce(alt, ""),\n  asset->{_id, url, "width": metadata.dimensions.width, "height": metadata.dimensions.height, "lqip": metadata.lqip}\n}}\n}': ProjectQueryResult
    '*[_type == "guide" && defined(slug.current)] | order(publishedAt desc){_id, title, "slug": slug.current, excerpt, publishedAt, "coverImage": coverImage{\n  ...,\n  "alt": coalesce(alt, ""),\n  asset->{_id, url, "width": metadata.dimensions.width, "height": metadata.dimensions.height, "lqip": metadata.lqip}\n}}': GuidesQueryResult
    '*[_type == "guide" && slug.current == $slug][0]{\n  _id,\n  _updatedAt,\n  title,\n  "slug": slug.current,\n  excerpt,\n  "coverImage": coverImage{\n  ...,\n  "alt": coalesce(alt, ""),\n  asset->{_id, url, "width": metadata.dimensions.width, "height": metadata.dimensions.height, "lqip": metadata.lqip}\n},\n  directAnswer,\n  body,\n  faqs,\n  author,\n  reviewer,\n  publishedAt,\n  lastReviewed,\n  "relatedServices": relatedServices[]->{\n  _id,\n  title,\n  "slug": slug.current,\n  icon,\n  menuSummary,\n  cardSummary,\n  isEmergency,\n  whatsappNoun,\n  "cardImage": cardImage{\n  ...,\n  "alt": coalesce(alt, ""),\n  asset->{_id, url, "width": metadata.dimensions.width, "height": metadata.dimensions.height, "lqip": metadata.lqip}\n}\n},\n  seo{metaTitle, metaDescription, noindex, canonicalOverride, extraJsonLd, "ogImage": ogImage{\n  ...,\n  "alt": coalesce(alt, ""),\n  asset->{_id, url, "width": metadata.dimensions.width, "height": metadata.dimensions.height, "lqip": metadata.lqip}\n}}\n}': GuideQueryResult
    '*[_type == "redirect"]{from, to, type}': RedirectsQueryResult
    '{\n  "pages": *[_type == "page" && defined(key)]{key, _updatedAt, "noindex": seo.noindex},\n  "services": *[_type == "service" && defined(slug.current)]{"slug": slug.current, _updatedAt, "noindex": seo.noindex},\n  "areas": *[_type == "area" && defined(slug.current)]{"slug": slug.current, _updatedAt, "noindex": seo.noindex},\n  "projects": *[_type == "project" && defined(slug.current)]{"slug": slug.current, _updatedAt, "noindex": seo.noindex},\n  "guides": *[_type == "guide" && defined(slug.current)]{"slug": slug.current, _updatedAt, "noindex": seo.noindex}\n}': SitemapQueryResult
